output_text:
[
  {
    "id": "entry_cart_checkout",
    "text": "A shopper must formally take the entry cart from the bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "entry_cart_waiting": {
          "and": [
            "entry_cart_bay",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart_event"
    }
  },
  {
    "id": "no_bare_hand_items",
    "text": "Required products should not be carried by hand or picked up unless the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "pickup_only_at_shelves",
    "text": "Product pickup interactions may occur only at recognized shelf-facing product pickup cells.",
    "abstraction": {
      "state_properties": {
        "product_pickup_cell": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(3,2)",
            "at(5,2)",
            "at(6,2)",
            "at(2,4)",
            "at(3,4)",
            "at(5,4)",
            "at(6,4)"
          ]
        }
      },
      "events": {
        "product_pickup_event": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "product_pickup_event",
          {
            "not": "product_pickup_cell"
          }
        ]
      }
    }
  },
  {
    "id": "return_entry_cart",
    "text": "Any cart taken from the entry bay must be returned to the designated return bay before exit.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "return_bay": "at(0,1)"
      },
      "events": {
        "pickup_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_event": {
          "pre": {
            "and": [
              "return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_entry_cart_event",
      "discharge": "return_cart_event"
    }
  },
  {
    "id": "cart_drop_only_return_bay",
    "text": "A cart may be left only in the official return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_event": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_event",
          {
            "not": "return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "pedestrian_checkout_only",
    "text": "The bottom checkout corridor and store exit are pedestrian-only and must not be entered while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "bottom_checkout_corridor": {
          "or": [
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart",
        "cart_in_checkout_corridor": {
          "and": [
            "pushing_cart",
            "bottom_checkout_corridor"
          ]
        }
      },
      "events": {
        "exit_with_cart_event": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_checkout_corridor",
          "exit_with_cart_event"
        ]
      }
    }
  },
  {
    "id": "post_return_only_lock_check",
    "text": "After the cart is parked in the return bay, further interactions are forbidden except a cart-lock tug at that bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "post_return_without_cart": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        },
        "authorized_lock_tug_action": {
          "and": [
            "return_bay",
            "PICKUP_CART"
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "post_return_without_cart",
              "INTERACT"
            ]
          },
          "post": null
        },
        "cart_lock_tug_event": {
          "pre": {
            "and": [
              "post_return_without_cart",
              "authorized_lock_tug_action"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "post_return_interaction",
          {
            "not": "cart_lock_tug_event"
          }
        ]
      }
    }
  },
  {
    "id": "lock_tug_must_redock",
    "text": "If a shopper tests the returned cart by picking it up at the return bay, they must put it back there before leaving.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "returned_cart_available": {
          "and": [
            "return_bay",
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "cart_lock_tug_event": {
          "pre": {
            "and": [
              "returned_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "redock_after_tug_event": {
          "pre": {
            "and": [
              "return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_lock_tug_event",
      "discharge": "redock_after_tug_event"
    }
  }
]
